/// <summary>
/// The NVTrvWorkerExpenseReqWFTypeSubmitManager menu item action event handler.
/// </summary>
public class NVTrvWorkerExpenseReqWFTypeSubmitManager 
{
}

Method.Source:
    public static void main(Args args)
	{
        WorkflowSubmitDialog    workflowSubmitDialog;
        WorkflowCorrelationId   workflowCorrelationId;
        WorkflowComment         workflowComment   = '';
        Recid                   recId = args.record().RecId;
        WorkflowTypeName        workflowTypeName  =  workflowTypeStr(NVTrvWorkerExpenseReqWFType);
        NVTrvWorkerExpenseReqWFTypeSubmitManager workflowSubmitManager = new NVTrvWorkerExpenseReqWFTypeSubmitManager();
        workflowSubmitDialog  = WorkflowSubmitDialog::construct(args.caller().getActiveWorkflowConfiguration());
        workflowSubmitDialog.run();

        // Check if user submits request to workflow
        if (workflowSubmitDialog.parmIsClosedOK())
        {
            NVTrvWorkerExpenseRequest   requestTable = args.record();
            workflowComment  = workflowSubmitDialog.parmWorkflowComment();
            try
            {
                workflowCorrelationId  = Workflow::activateFromWorkflowType(workflowTypeName, recId, workflowComment, NoYes::No);
                ttsbegin;
                NVTrvWorkerExpenseRequest::updateWorkflowStatus(recId, NVTrvWorkerExpReqWFStatus::Submitted);
                ttscommit;
                info("Submitted to workflow");
            }
            catch (Exception::Error)
            {
                error("Error on workflow activation");
            }
        }
        args.caller().updateWorkFlowControls();

        Object callerForm = args.caller();
        FormDataSource fds = args.record().datasource();
        if(callerForm)
        {
            fds.refresh();
            fds.research(true);
        }
    }
